#!/bin/bash
# Download all data and models needed for this environment.
#
# Idempotent; safe to run multiple times.
#
# Estimated total download size: 0 GB
# Estimated disk usage after extraction: 0 GB
#
# Nothing is fetched from external sources: the benchmark uses no public
# datasets or pretrained weights. Its public training/dev data are small
# agent-generated CSV files tracked in git under data/three_spin_binary/, and
# the frozen comparison baseline models are tracked under eval/*/baselines/
# (regenerated by scripts/baseline.sh).

set -e

cd /home/user

mkdir -p data/downloads
echo "Nothing to download: all inputs are tracked in git (data/three_spin_binary/)."
